.ds-menu {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  width: max-content;
  padding: 2px 4px;
  border-radius: var(--menu-radius, 999px);
  isolation: isolate;
}

.ds-menu__pill {
  position: absolute;
  z-index: -1;
  top: 2px;
  left: 0;
  height: 32px;
  border-radius: var(--menu-radius, 999px);
  pointer-events: none;
  background:
    radial-gradient(ellipse at 88% 92%, rgb(96 181 255 / 8%), rgb(96 181 255 / 2%) 48%, transparent 66%),
    linear-gradient(180deg, rgb(255 255 255 / 76%), rgb(242 247 252 / 68%) 48%, rgb(224 237 248 / 72%));
  box-shadow:
    0 0 0 0.5px rgb(10 37 64 / 5%),
    0 1px 1px -0.5px rgb(10 37 64 / 12%),
    0 4px 6px -5px rgb(10 37 64 / 5%),
    inset 0 0 0 0.5px rgb(10 37 64 / 12%),
    inset 0 1px 0 rgb(255 255 255 / 78%),
    inset 0 2px 3px -3px rgb(255 255 255 / 55%),
    inset 0 -1px 0 rgb(10 37 64 / 9%),
    inset 0 -3px 5px -5px rgb(10 37 64 / 28%);
}

.ds-menu__pill::before,
.ds-menu__pill::after {
  content: "";
  position: absolute;
  inset: 1px;
  border-radius: inherit;
}

.ds-menu__pill::before {
  opacity: 0.5;
  background:
    linear-gradient(180deg, rgb(255 255 255 / 25%), transparent 34%),
    linear-gradient(90deg, rgb(10 37 64 / 2%), transparent 24%, transparent 78%, rgb(31 112 186 / 2.7%));
}

.ds-menu__pill::after {
  opacity: 0.46;
  background:
    radial-gradient(circle at 48% 30%, rgb(255 255 255 / 38%), rgb(255 255 255 / 16%) 14%, rgb(255 255 255 / 5%) 30%, transparent 54%),
    linear-gradient(108deg, transparent 30%, rgb(10 37 64 / 2.4%) 39%, rgb(255 255 255 / 26%) 49%, rgb(31 112 186 / 2.7%) 58%, transparent 70%);
}

.ds-menu--ready .ds-menu__pill {
  /* Only this absolutely positioned decoration changes width; siblings never reflow. */
  transition: transform var(--menu-duration, 340ms) var(--menu-ease, cubic-bezier(0.22, 1, 0.36, 1)), width var(--menu-duration, 340ms) var(--menu-ease, cubic-bezier(0.22, 1, 0.36, 1));
}

.ds-menu__item {
  appearance: none;
  display: flex;
  position: relative;
  flex: none;
  align-items: center;
  gap: 6px;
  border: 0;
  border-radius: var(--menu-radius, 999px);
  padding: 6px 10px;
  background: transparent;
  color: var(--menu-muted, #637488);
  font-family: "Inter", sans-serif;
  font-size: 13.7px;
  font-weight: 500;
  line-height: 20px;
  white-space: nowrap;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: color 160ms ease-out, background-color 160ms ease-out;
}

.ds-menu__item:nth-of-type(2) { font-size: 13.9px; }
.ds-menu__item:nth-of-type(3) { font-size: 13.8px; }
.ds-menu__item:nth-of-type(4) { font-size: 13.5px; }

.ds-menu__item[aria-pressed="true"] { color: var(--menu-ink, #0a2540); }

@media (hover: hover) {
  .ds-menu__item[aria-pressed="false"]:hover {
    color: var(--menu-ink, #0a2540);
    background-color: rgb(10 37 64 / 3%);
  }
}

.ds-menu__item:focus-visible {
  outline: 2px solid var(--menu-focus, #1f70ba);
  outline-offset: 3px;
}

.ds-menu__icon {
  display: block;
  flex: none;
  width: 16px;
  height: 16px;
}

@media (prefers-reduced-motion: reduce) {
  .ds-menu--ready .ds-menu__pill,
  .ds-menu__item {
    transition: none;
  }
}

.ds-menu__item[aria-pressed="true"] {isolation:isolate;} .ds-menu__item > .ds-menu__pill {inset:0 -2.35px; height:32px;}

